[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林小雨",
      "role": "protagonist",
      "identity": "高三女生，被霸凌者",
      "traits": ["内向敏感", "坚韧执着", "情感细腻", "孤独", "勇敢"],
      "overt_motivation": "躲避霸凌，寻找安全的避难所",
      "covert_motivation": "渴望被理解和陪伴，希望有人能听见她的声音",
      "secret_fear": "害怕永远孤独，害怕重要的记忆会消失",
      "misperception_of_other": "以为男主只是偶然出现在透明层的幽灵，不知道他一直在她身边",
      "hidden_connection": "三年前曾是男主的同桌，男主暗恋她但从未表白"
    },
    {
      "name": "沈墨",
      "role": "deuteragonist",
      "identity": "失踪三年的学霸，被困在透明层",
      "traits": ["温柔体贴", "聪明理性", "隐忍克制", "深情专一", "绝望中仍存希望"],
      "overt_motivation": "想要告诉小雨真相，希望她能安全",
      "covert_motivation": "渴望被看见和记住，希望能与小雨真正交流一次",
      "secret_fear": "害怕小雨永远不会知道他的存在，害怕自己会彻底消失",
      "misperception_of_other": "以为小雨一直听不见他说话，不知道她其实能感受到他的存在",
      "hidden_connection": "三年前为了保护小雨而意外触发透明规则，从此被困"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈美琪",
      "function": "阻碍",
      "identity": "班级霸凌者",
      "description": "嫉妒小雨的成绩和安静气质，带头孤立和欺负她"
    },
    {
      "name": "王老师",
      "function": "助力",
      "identity": "班主任",
      "description": "关心学生但对霸凌事件处理不当，无意中推动了小雨触发规则"
    },
    {
      "name": "张浩",
      "function": "反转点",
      "identity": "沈墨的好友",
      "description": "知道沈墨失踪的真相，但在关键时刻选择沉默"
    }
  ],
  "relationship_dynamics": "林小雨和沈墨之间存在着错位的双向暗恋：沈墨三年来一直在小雨耳边说话却以为她听不见，小雨能感受到某种陪伴却不知道是谁。当小雨终于能看见沈墨时，24小时后她将遗忘这一切，形成'看得见却触不到，记得却必须忘'的悲剧循环。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立规则怪谈世界观，引入女主林小雨的困境，展示她如何触发透明规则并首次遇见沈墨",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "监控死角的三分钟",
        "core_event": "林小雨为躲避霸凌躲进监控死角，意外触发透明规则，发现自己能看见失踪三年的沈墨",
        "emotional_tone": "紧张、恐惧、震惊",
        "key_scenes": ["霸凌场景", "躲进死角倒计时", "变成透明人", "看见沈墨的震撼"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "另一个世界的你",
        "core_event": "小雨与沈墨开始交流，发现他三年来一直在她身边说话，但两人都不知道对方能感知自己",
        "emotional_tone": "困惑、温暖、心痛",
        "key_scenes": ["初次对话", "回忆三年前", "沈墨的守护日常", "时间流逝的焦虑"]
      }
    ],
    "turning_point": "小雨意识到24小时后她会忘记这一切，而沈墨告诉她这已经不是第一次了"
  },
  "act_two": {
    "description": "深入探索透明层的秘密，两人在有限时间内加深了解，同时揭示三年前的真相",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "循环的记忆",
        "core_event": "沈墨透露小雨之前也曾多次触发规则见过他，但每次都会遗忘，他一直在等待她再次回来",
        "emotional_tone": "绝望、执着、温柔",
        "key_scenes": ["沈墨的日志", "之前的相遇片段", "小雨的愧疚", "时间紧迫感"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "三年前的真相",
        "core_event": "揭露沈墨失踪的真相：他为了保护小雨免受霸凌而故意引开霸凌者，结果意外触发规则被困",
        "emotional_tone": "震撼、感动、痛苦",
        "key_scenes": ["回忆闪回", "沈墨的牺牲", "小雨的自责", "现实世界的危机"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "最后的十二小时",
        "core_event": "小雨决定利用剩余时间帮助沈墨寻找解脱的方法，两人在透明层中共同探索规则的边界",
        "emotional_tone": "急迫、希望、不舍",
        "key_scenes": ["寻找规则漏洞", "其他透明人的线索", "告白时刻", "倒计时压力"]
      }
    ],
    "turning_point": "小雨发现唯一能让沈墨解脱的方法是她永远不再触发规则，这意味着他们将永远分离"
  },
  "act_three": {
    "description": "高潮对决和BE结局，小雨做出最终选择，接受失去所爱的命运",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "看得见却触不到",
        "core_event": "小雨在最后时刻向沈墨表白，两人终于确认彼此的感情，但时间即将耗尽",
        "emotional_tone": "极致虐心、深情、绝望",
        "key_scenes": ["告白场景", "无法触碰的拥抱", "沈墨的眼泪", "最后的告别"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "记得却必须忘",
        "core_event": "小雨回到现实世界，忘记了24小时内的一切，但内心深处留下无法解释的空洞和悲伤",
        "emotional_tone": "空虚、迷茫、宿命感",
        "key_scenes": ["记忆清除", "回到教室", "莫名的泪水", "沈墨在透明层中的守望"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "永恒的守望者",
        "core_event": "故事结尾暗示这是一个无尽的循环，沈墨将继续在透明层中等待，而小雨可能会再次触发规则",
        "emotional_tone": "宿命、无力、微弱希望",
        "key_scenes": ["新的霸凌威胁", "小雨走向死角", "沈墨的期待", "循环的开始"]
      }
    ]
  }
}"}]

